// EasyJava 2 - program okienkowy Windows, uruchamiany bez Node.js.
// EASYJAVA_PROJECT_V2:
// Ten plik jest jednoczesnie programem i edytowalnym projektem EasyJava.
var shell = new ActiveXObject("WScript.Shell");
var fs = new ActiveXObject("Scripting.FileSystemObject");
var dir = null, exitCode = 0;
var testing = WScript.Arguments.Named.Exists("easyjava-test");
try {
  dir = fs.BuildPath(fs.GetSpecialFolder(2), "EasyJava_" + fs.GetTempName());
  fs.CreateFolder(dir);
  var exe = fs.BuildPath(dir, "easyjava-player.exe");
  var xml = new ActiveXObject("Msxml2.DOMDocument.6.0");
  var data = xml.createElement("binary"); data.dataType = "bin.base64";
  data.text = "";
  var stream = new ActiveXObject("ADODB.Stream"); stream.Type = 1; stream.Open();
  stream.Write(data.nodeTypedValue); stream.SaveToFile(exe, 2); stream.Close();
  var mode = testing ? "--smoke" : "--player";
  exitCode = shell.Run('"' + exe + '" ' + mode + ' "' + WScript.ScriptFullName + '"', testing ? 0 : 1, true);
} catch (e) { exitCode = 1; if (testing) WScript.Echo(e.message); else shell.Popup("Nie mozna uruchomic programu EasyJava:\n" + e.message, 0, "EasyJava", 16); }
finally { if (dir != null && fs.FolderExists(dir)) { try { fs.DeleteFolder(dir, true); } catch (ignored) {} } }
WScript.Quit(exitCode);
